'use strict';

const { Store } = require('./store');
const { KeyedLock } = require('./keyed-lock');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;
const SKU_PREFIX = 'sku:';
const ORDER_PREFIX = 'order:';

// Locks are shared by every service over the same store object, so one
// service per worker still gets mutual exclusion. They only cover this
// process; the store offers no compare-and-set to coordinate across processes.
const locksByStore = new WeakMap();

function locksFor(store) {
  let locks = locksByStore.get(store);
  if (!locks) {
    locks = new KeyedLock();
    locksByStore.set(store, locks);
  }
  return locks;
}

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. Each
 * read-modify-write locks the keys it touches: the order first, then its SKUs
 * in sorted order. A call waits only for calls that lock one of the same
 * keys, so calls that share no SKU and no order do not wait for each other,
 * except that a bundle holds the SKUs it has already locked while it queues
 * for the rest. Reads (`available`, `snapshot`) take no lock.
 */
class InventoryService {
  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
  }

  // Looked up per call so the locks follow `this.store` if it is replaced.
  get #locks() {
    return locksFor(this.store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    const key = skuKey(sku);
    return this.#locks.run([key], async () => {
      const item = (await this.store.get(key)) || { stock: 0, reserved: 0, sold: 0 };
      const next = { ...item, stock: item.stock + qty };
      await this.store.set(key, next);
      return { sku, ...next };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    // Copied before the first await, so changes the caller makes to `items`
    // while the call is in flight cannot change what gets held.
    const wanted = items.map(({ sku, qty }) => ({ sku, qty }));
    const key = orderKey(orderId);
    return this.#locks.run([key], async () => {
      const existing = await this.store.get(key);
      if (existing) {
        return toReservation(existing);
      }
      const order = { orderId, items: wanted, status: 'reserved', createdAt: this.now() };
      await this.#updateSkus(wanted, holdUnits, () => this.store.set(key, order));
      return toReservation(order);
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    const key = orderKey(orderId);
    return this.#locks.run([key], async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      const committed = { ...order, status: 'committed' };
      await this.#updateSkus(order.items, sellUnits, () => this.store.set(key, committed));
      return toReservation(committed);
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#locks.run([orderKey(orderId)], async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return toReservation(await this.#releaseHeld(order));
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const released = [];
    for (const key of await this.store.keys(ORDER_PREFIX)) {
      // One order at a time, each re-read under its lock: checkout may have
      // committed or released it since the listing, and holding one order
      // lock at a time keeps the lock order used by the other methods.
      const expired = await this.#locks.run([key], async () => {
        const order = await this.store.get(key);
        const stale = order.createdAt < cutoff;
        if (order.status !== 'reserved' || !stale) {
          return null;
        }
        return this.#releaseHeld(order);
      });
      if (expired) {
        released.push(expired.orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  // The caller must hold the order's lock and have checked it is reserved.
  async #releaseHeld(order) {
    const released = { ...order, status: 'released' };
    await this.#updateSkus(order.items, returnUnits, () => this.store.set(orderKey(order.orderId), released));
    return released;
  }

  /**
   * Under the locks of every SKU in `entries`: read them, compute each new
   * value with `change(item, entry)`, write them all, then call `persist` to
   * write the order. Every `change` runs before the first write, so a throw
   * or an unknown SKU leaves the store untouched. If any write fails, the
   * SKUs are put back to the values read under the lock.
   *
   * Values from the store are never mutated: a store that hands out live
   * references would otherwise see a change before it was written.
   */
  async #updateSkus(entries, change, persist) {
    const keys = entries.map(({ sku }) => skuKey(sku));
    await this.#locks.run(keys, async () => {
      const before = await Promise.all(keys.map(key => this.store.get(key)));
      const after = entries.map((entry, i) => {
        if (!before[i]) {
          throw new UnknownSkuError(entry.sku);
        }
        return change(before[i], entry);
      });
      try {
        await settleAll(keys.map(async (key, i) => this.store.set(key, after[i])));
        await persist();
      } catch (err) {
        await this.#restore(keys, before, err);
        throw err;
      }
    });
  }

  async #restore(keys, values, cause) {
    const results = await Promise.allSettled(keys.map(async (key, i) => this.store.set(key, values[i])));
    const failures = results.filter(result => result.status === 'rejected').map(result => result.reason);
    if (failures.length > 0) {
      throw new AggregateError(
        [cause, ...failures],
        `store write failed, and restoring ${keys.join(', ')} also failed; their counters need a manual check`
      );
    }
  }
}

function holdUnits(item, { sku, qty }) {
  const free = item.stock - item.reserved;
  if (free < qty) {
    throw new InsufficientStockError(sku, qty, free);
  }
  return { ...item, reserved: item.reserved + qty };
}

function sellUnits(item, { qty }) {
  return { ...item, stock: item.stock - qty, reserved: item.reserved - qty, sold: item.sold + qty };
}

function returnUnits(item, { qty }) {
  return { ...item, reserved: item.reserved - qty };
}

// Like Promise.all, but waits for every write to finish before rejecting, so
// a rollback never races a write that is still in flight. Callers pass async
// functions' promises, so a store that throws synchronously is waited for too.
async function settleAll(promises) {
  const results = await Promise.allSettled(promises);
  const failed = results.find(result => result.status === 'rejected');
  if (failed) {
    throw failed.reason;
  }
}

function skuKey(sku) {
  return `${SKU_PREFIX}${sku}`;
}

function orderKey(orderId) {
  return `${ORDER_PREFIX}${orderId}`;
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

