   * when that call arrives; the call proceeds after `open()`.
   */
  stallNext(op, key) {
    let arrive;
    let open;
    const reached = new Promise(resolve => { arrive = resolve; });
    const opened = new Promise(resolve => { open = resolve; });
    this.gates.push({ op, key, arrive, opened });
    return { reached, open };
  }

  async pass(op, key) {
    const index = this.gates.findIndex(gate => gate.op === op && gate.key === key);
    if (index === -1) {
      return;
    }
    const [gate] = this.gates.splice(index, 1);
    gate.arrive();
    await gate.opened;
  }

  async get(key) {
    await this.pass('get', key);
    return this.inner.get(key);
  }

  async set(key, value) {
    await this.pass('set', key);
    return this.inner.set(key, value);
  }

  async keys(prefix) {
    await this.pass('keys', prefix);
    return this.inner.keys(prefix);
  }
}

/** Rejects chosen calls, to exercise the service's handling of store errors. */
class FlakyStore {
  constructor(inner = new Store()) {
    this.inner = inner;
    this.failures = [];
  }

