   * Make one upcoming `op` call on `key` reject, after letting `skip`
   * matching calls through. Returns the error it will reject with.
   */
  failNext(op, key, { skip = 0, error = new Error(`store unavailable: ${op} ${key}`) } = {}) {
    this.failures.push({ op, key, skip, error });
    return error;
  }

  async maybeFail(op, key) {
    await ticks(1);
