'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  ValidationError,
  UnknownSkuError,
  InsufficientStockError
} = require('../src');
const {
  ticks,
  createRng,
  GatedStore,
  FlakyStore,
  JitterStore,
  SharedReferenceStore,
  assertCountersMatchOrders
} = require('./helpers/stores');

async function stocked(stock, store = new Store()) {
  const svc = new InventoryService({ store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return { svc, store };
}

describe('adjustStock', () => {
  test('a positive delta adds units and resolves to the snapshot', async () => {
    const { svc } = await stocked({ a: 5 });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    assert.deepEqual(await svc.adjustStock('a', 7, 'found a pallet'), { sku: 'a', stock: 12, reserved: 2, sold: 0 });
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 12, reserved: 2, sold: 0 });
  });

  test('a negative delta removes units', async () => {
    const { svc } = await stocked({ a: 10 });
    assert.deepEqual(await svc.adjustStock('a', -4, 'damaged'), { sku: 'a', stock: 6, reserved: 0, sold: 0 });
  });

  test('a removal may take stock down to exactly the reserved units', async () => {
    const { svc } = await stocked({ a: 10 });
    await svc.reserve('o1', [{ sku: 'a', qty: 3 }]);
    assert.deepEqual(await svc.adjustStock('a', -7, 'count'), { sku: 'a', stock: 3, reserved: 3, sold: 0 });
    assert.equal(await svc.available('a'), 0);
  });

  test('a removal below the reserved units rejects and changes nothing', async () => {
    const { svc } = await stocked({ a: 10 });
    await svc.reserve('o1', [{ sku: 'a', qty: 3 }]);
    await assert.rejects(svc.adjustStock('a', -8, 'count'), err => {
      assert.ok(err instanceof InsufficientStockError);
      assert.equal(err.sku, 'a');
      assert.equal(err.requested, 8);
      assert.equal(err.available, 7);
      return true;
    });
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 10, reserved: 3, sold: 0 });
  });

  test('keeps sold units and leaves other skus alone', async () => {
    const { svc } = await stocked({ a: 10, b: 4 });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    await svc.commit('o1');
    assert.deepEqual(await svc.adjustStock('a', -3, 'count'), { sku: 'a', stock: 5, reserved: 0, sold: 2 });
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 4, reserved: 0, sold: 0 });
  });

  test('an unknown sku rejects with UnknownSkuError and creates nothing', async () => {
    const { svc, store } = await stocked({ a: 1 });
    await assert.rejects(svc.adjustStock('ghost', 5, 'count'), UnknownSkuError);
    await assert.rejects(svc.adjustStock('ghost', -5, 'count'), UnknownSkuError);
    assert.equal(await store.get('sku:ghost'), undefined);
  });

  test('rejects invalid arguments with ValidationError', async () => {
    const { svc } = await stocked({ a: 10 });
    const badDeltas = [0, -0, 1.5, NaN, Infinity, '3', null, undefined, 1n, [], {}];
    for (const delta of badDeltas) {
      await assert.rejects(svc.adjustStock('a', delta, 'count'), ValidationError, `delta ${String(delta)}`);
    }
    const badReasons = ['', '   ', undefined, null, 5, {}, ['count']];
    for (const reason of badReasons) {
      await assert.rejects(svc.adjustStock('a', 1, reason), ValidationError, `reason ${String(reason)}`);
    }
    for (const sku of ['', '  ', undefined, 7]) {
      await assert.rejects(svc.adjustStock(sku, 1, 'count'), ValidationError);
    }
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 10, reserved: 0, sold: 0 });
  });

  test('validation takes priority over an unknown sku', async () => {
    const { svc } = await stocked({});
    await assert.rejects(svc.adjustStock('ghost', 0, 'count'), ValidationError);
    await assert.rejects(svc.adjustStock('ghost', 1, ''), ValidationError);
  });

  test('the resolved snapshot is a copy, not the stored record', async () => {
    const store = new SharedReferenceStore();
    const { svc } = await stocked({ a: 5 }, store);
    const snap = await svc.adjustStock('a', 1, 'count');
    snap.stock = 999;
    assert.equal((await svc.snapshot('a')).stock, 6);
  });

  test('does not mutate the stored record before the write', async () => {
    const store = new SharedReferenceStore();
    const { svc } = await stocked({ a: 5 }, store);
    const held = await store.get('sku:a');
    await svc.adjustStock('a', 3, 'count');
    assert.equal(held.stock, 5);
  });

  test('a failed write rejects with the store error and changes nothing', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, store);
    const error = store.failNext('set', 'sku:a');
    await assert.rejects(svc.adjustStock('a', 2, 'count'), err => err === error);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 0, sold: 0 });
    assert.equal((await svc.adjustStock('a', 2, 'count')).stock, 7);
  });

  test('a failed read rejects and the sku lock is released', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, store);
    const error = store.failNext('get', 'sku:a');
    await assert.rejects(svc.adjustStock('a', 2, 'count'), err => err === error);
    assert.equal((await svc.adjustStock('a', 2, 'count')).stock, 7);
  });

  test('concurrent adjustments do not lose updates', async () => {
    const { svc } = await stocked({ a: 100 }, new JitterStore(11));
    await Promise.all(Array.from({ length: 40 }, (_, i) => svc.adjustStock('a', i % 2 === 0 ? 3 : -1, 'count')));
    assert.equal((await svc.snapshot('a')).stock, 100 + 20 * 3 - 20);
  });

  test('concurrent removals cannot take stock below the reserved units', async () => {
    const { svc } = await stocked({ a: 10 });
    await svc.reserve('o1', [{ sku: 'a', qty: 4 }]);
    const results = await Promise.allSettled(Array.from({ length: 10 }, () => svc.adjustStock('a', -2, 'count')));
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 3);
    for (const r of results.filter(r => r.status === 'rejected')) {
      assert.ok(r.reason instanceof InsufficientStockError);
    }
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 4, reserved: 4, sold: 0 });
  });

  test('a removal waits for an in-flight reserve instead of racing it', async () => {
    const store = new GatedStore();
    const { svc } = await stocked({ a: 5 }, store);
    const stall = store.stallNext('set', 'sku:a');
    const reserve = svc.reserve('o1', [{ sku: 'a', qty: 5 }]);
    await stall.reached;

    const adjust = svc.adjustStock('a', -3, 'count');
    await ticks(20);
    stall.open();

    await reserve;
    await assert.rejects(adjust, err => err instanceof InsufficientStockError && err.available === 0);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 5, sold: 0 });
  });

  test('a reserve waits for an in-flight adjustment instead of overselling', async () => {
    const store = new GatedStore();
    const { svc } = await stocked({ a: 5 }, store);
    const stall = store.stallNext('set', 'sku:a');
    const adjust = svc.adjustStock('a', -4, 'count');
    await stall.reached;

    const reserve = svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    await ticks(20);
    stall.open();

    assert.equal((await adjust).stock, 1);
    await assert.rejects(reserve, InsufficientStockError);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 1, reserved: 0, sold: 0 });
  });

  test('counters stay consistent with orders under mixed traffic', async () => {
    for (const seed of [1, 2, 3]) {
      const store = new JitterStore(seed);
      const { svc } = await stocked({ a: 20, b: 20 }, store);
      const rng = createRng(seed);
      let adjusted = { a: 0, b: 0 };
      const calls = [];
      for (let i = 0; i < 60; i++) {
        const sku = rng() < 0.5 ? 'a' : 'b';
        const roll = rng();
        if (roll < 0.4) {
          calls.push(svc.reserve(`o${i}`, [{ sku, qty: 1 + Math.floor(rng() * 3) }]).catch(() => {}));
        } else if (roll < 0.6) {
          const delta = Math.floor(rng() * 7) - 3 || 1;
          calls.push(svc.adjustStock(sku, delta, 'count').then(() => { adjusted[sku] += delta; }, () => {}));
        } else if (roll < 0.8) {
          calls.push(svc.commit(`o${i - 3}`).catch(() => {}));
        } else {
          calls.push(svc.release(`o${i - 5}`).catch(() => {}));
        }
      }
      await Promise.all(calls);
      await assertCountersMatchOrders(assert, svc, store, { a: 20 + adjusted.a, b: 20 + adjusted.b });
      for (const sku of ['a', 'b']) {
        const snap = await svc.snapshot(sku);
        assert.ok(snap.stock >= snap.reserved, `${sku} stock fell below reserved`);
      }
    }
  });
});
